mapper.select:
SELECT id, member_id, category_id, content, image_url, like_count, view_count, subscriber_only, created_at, updated_at
FROM post
WHERE id = #{id}

SELECT id, member_id, category_id, content, image_url, like_count, view_count, subscriber_only, created_at, updated_at
FROM post
WHERE subscriber_only = FALSE


    AND id  <  #{cursor}

ORDER BY id DESC
LIMIT #{size}

SELECT p.id, p.member_id, p.category_id, p.content, p.image_url, p.like_count, p.view_count, p.subscriber_only, p.created_at, p.updated_at
FROM post p
INNER JOIN subscription s
ON s.target_id = p.member_id
WHERE s.member_id = #{memberId}
AND s.status_id = 15
AND p.subscriber_only = TRUE


    AND p.id  <  #{cursor}

ORDER BY p.id DESC
LIMIT #{size}
